 Chapter 2 Within-Slice Spatial Analysis # Install packages if not already installed # install.packages(c(&quot;Seurat&quot;, &quot;Matrix&quot;, &quot;ggplot2&quot;, &quot;viridis&quot;, &quot;patchwork&quot;, &quot;dplyr&quot;)) # install.packages(c(&quot;sp&quot;, &quot;spdep&quot;, &quot;spatstat&quot;, &quot;pheatmap&quot;, &quot;sctransform&quot;)) # SeuratData::InstallData(&quot;stxBrain.SeuratData&quot;) # devtools::install_github(&#39;satijalab/seurat-data&#39;) # Load essential libraries library(Seurat) # v5.3.1 - main spatial analysis package library(ggplot2) # for visualization library(dplyr) # for data manipulation library(Matrix) # for sparse matrices library(viridis) # for color palettes library(patchwork) # for combining plots library(spdep) # for spatial statistics library(pheatmap) # for heatmaps library(sctransform) # for SCTransform normalization library(future) # for parallel processing library(knitr) # for visualising tables # Set up parallel processing for faster computation plan(&quot;multisession&quot;, workers = 4) # Increase the memory limit for parallel processing options(future.globals.maxSize = 8000 * 1024^2) # Set to 4GB # Set seed for reproducibility set.seed(42) seurat_obj &lt;- readRDS(&quot;cache/stxBrain_anterior2.RDS&quot;) seurat_obj &lt;- UpdateSeuratObject(seurat_obj) This chapter starts from the SCTransform-normalized and clustered object produced by the quality-control chapter. 2.1 1 Gene Expression Patterns 2.1.1 1.1 Spatial Expression of Top Expressed Brain Markers neuronal markers: Snap25, Rbfox3, Tubb3, Camk2a, Nrgn, Syp, Syn1 excitatory_genes: Slc17a7, Slc17a6, Camk2a, Gria1, Gria2 inhibitory_genes: Gad1, Gad2, Slc6a1, Pvalb, Sst, Vip myelin_genes: Mbp, Plp1, Mog, Olig2, Olig1 2.1.2 1.2 Select top Genes From each category above we select a gene with the highest expression across spots. If none found we fallback to top expressed genes in the slice. # Get all available genes all_genes &lt;- rownames(seurat_obj) # These are genes known to have distinct spatial expression in brain tissue # Look for key brain marker genes neuronal_genes &lt;- grep(&quot;^(Snap25|Rbfox3|Tubb3|Camk2a|Nrgn|Syp|Syn1)&quot;, all_genes, value = TRUE, ignore.case = T) excitatory_genes &lt;- grep(&quot;^(Slc17a7|Slc17a6|Camk2a|Gria1|Gria2)&quot;, all_genes, value = TRUE, ignore.case = T) inhibitory_genes &lt;- grep(&quot;^(Gad1|Gad2|Slc6a1|Pvalb|Sst|Vip)&quot;, all_genes, value = TRUE, ignore.case = T) myelin_genes &lt;- grep(&quot;^(Mbp|Plp1|Mog|Olig2|Olig1)&quot;, all_genes, value = TRUE, ignore.case = T) astrocyte_genes &lt;- grep(&quot;^(Gfap|Aqp4|Slc1a3|Slc1a2|Aldh1l1)&quot;, all_genes, value = TRUE, ignore.case = T) microglia_genes &lt;- grep(&quot;^(Cx3cr1|Iba1|Aif1|Tmem119|P2ry12)&quot;, all_genes, value = TRUE, ignore.case = T) # Function to select best available gene from a list select_best_gene &lt;- function(gene_list, seurat_obj) { if(length(gene_list) == 0) return(NULL) # Get expression levels for all genes in the list expr_data &lt;- GetAssayData(seurat_obj, assay = &quot;SCT&quot;, layer = &quot;data&quot;) available_genes &lt;- gene_list[gene_list %in% rownames(expr_data)] if(length(available_genes) == 0) return(NULL) # Calculate mean expression for each gene mean_expr &lt;- sapply(available_genes, function(g) mean(expr_data[g, ])) # Select gene with highest mean expression best_gene &lt;- names(sort(mean_expr, decreasing = TRUE))[1] return(best_gene) } # Select representative genes for different brain cell types/regions selected_genes &lt;- list( neuronal = select_best_gene(neuronal_genes, seurat_obj), excitatory = select_best_gene(excitatory_genes, seurat_obj), inhibitory = select_best_gene(inhibitory_genes, seurat_obj), oligodendrocyte = select_best_gene(myelin_genes, seurat_obj) ) # Remove NULL entries selected_genes &lt;- selected_genes[!sapply(selected_genes, is.null)] # If we couldn&#39;t find specific brain genes, use top variable features if( length(selected_genes) &lt; 4) { print(&quot;Using top variable features as some brain-specific genes were not found...&quot;) top_var_genes &lt;- VariableFeatures(seurat_obj)[1:8] # Add additional genes to reach 4 total additional_genes &lt;- top_var_genes[!top_var_genes %in% unlist(selected_genes)] if(length(selected_genes) &lt; 4) { remaining_needed &lt;- 4 - length(selected_genes) for(i in 1:remaining_needed) { if(i &lt;= length(additional_genes)) { selected_genes[[paste0(&quot;variable_&quot;, i)]] &lt;- additional_genes[i] } } } } # Display selected genes selectGeneTable &lt;- data.frame() for(i in 1:length(selected_genes)) { gene_name &lt;- selected_genes[[i]] gene_type &lt;- names(selected_genes)[i] # Get expression statistics expr_data &lt;- GetAssayData(seurat_obj, assay = &quot;SCT&quot;, layer = &quot;data&quot;) gene_expr &lt;- expr_data[gene_name, ] mean_expr &lt;- round(mean(gene_expr), 3) pct_expressing &lt;- round(100 * sum(gene_expr &gt; 0) / length(gene_expr), 1) tmp &lt;- data.frame(Type=gene_type, Name=gene_name, `Mean Expr`=mean_expr, `% expressing`=paste0(pct_expressing, &quot;%&quot;), check.names = F ) selectGeneTable &lt;- rbind(selectGeneTable, tmp) } selectGeneTable %&gt;% knitr::kable() Type Name Mean Expr % expressing neuronal Snap25 3.525 100% excitatory Camk2a 2.081 98.9% inhibitory Gad1 1.923 95.3% oligodendrocyte Mbp 3.680 99.9% 2.1.3 1.3 Visualise Top Expressed Genes # Function to create spatial gene expression plot using Seurat plot_spatial_gene &lt;- function(seurat_obj, gene_name, title = NULL) { if(!gene_name %in% rownames(seurat_obj)) { print(paste(&quot;Gene&quot;, gene_name, &quot;not found in dataset&quot;)) return(NULL) } # Use Seurat&#39;s SpatialFeaturePlot p &lt;- SpatialFeaturePlot( seurat_obj, features = gene_name, pt.size.factor = 1.6, # Adjust spot size alpha = c(0.1, 1) # Transparency range ) + scale_fill_viridis_c(option = &quot;magma&quot;) + # Use magma color palette theme( plot.title = element_text(size = 12), legend.text = element_text(size = 8), legend.title = element_text(size = 9) ) # Add custom title if provided if(!is.null(title)) { p &lt;- p + ggtitle(paste(title, &quot;-&quot;, gene_name)) } return(p) } # Create individual plots for selected genes plot_list &lt;- list() plot_titles &lt;- c(&quot;Neuronal Marker&quot;, &quot;Excitatory Marker&quot;, &quot;Inhibitory Marker&quot;, &quot;Oligodendrocyte Marker&quot;) for(i in 1:min(4, length(selected_genes))) { gene_name &lt;- selected_genes[[i]] title &lt;- if(i &lt;= length(plot_titles)) plot_titles[i] else paste(&quot;Gene&quot;, i) plot_obj &lt;- plot_spatial_gene(seurat_obj, gene_name, title) if(!is.null(plot_obj)) { plot_list[[i]] &lt;- plot_obj } } # Remove NULL plots plot_list &lt;- plot_list[!sapply(plot_list, is.null)] # Create combined plot using patchwork if(length(plot_list) &gt;= 4) { gene_plots &lt;- (plot_list[[1]] | plot_list[[2]]) / (plot_list[[3]] | plot_list[[4]]) } else if(length(plot_list) == 3) { gene_plots &lt;- plot_list[[1]] / (plot_list[[2]] | plot_list[[3]]) } else if(length(plot_list) == 2) { gene_plots &lt;- plot_list[[1]] | plot_list[[2]] } else if(length(plot_list) == 1) { gene_plots &lt;- plot_list[[1]] } else { # Fallback: use top variable features print(&quot;Creating plots with top variable features...&quot;) top_genes &lt;- VariableFeatures(seurat_obj)[1:4] p1 &lt;- plot_spatial_gene(seurat_obj, top_genes[1], &quot;Variable Gene 1&quot;) p2 &lt;- plot_spatial_gene(seurat_obj, top_genes[2], &quot;Variable Gene 2&quot;) p3 &lt;- plot_spatial_gene(seurat_obj, top_genes[3], &quot;Variable Gene 3&quot;) p4 &lt;- plot_spatial_gene(seurat_obj, top_genes[4], &quot;Variable Gene 4&quot;) gene_plots &lt;- (p1 | p2) / (p3 | p4) } print(gene_plots) Interpretation: Brain tissue shows distinct spatial gene expression patterns Neuronal markers: Often show layered or regional patterns Excitatory markers: Typically enriched in cortical regions Oligodendrocyte markers: Often concentrated in white matter regions These patterns reflect the anatomical organization of brain tissue 2.2 2. Autocorrelation Analysis There are two general ways to perform spatial autocorrelation: Statistics that measure the dependence of a feature on spatial location. Differential expression testing between pre-annotated anatomical regions Spatial autocorrelation is the degree to which nearby locations have similar values. CLICK HERE for more details Why It Matters for Spatial Transcriptomics Biological significance: Tissue organization: Cells of the same type cluster together spatially Morphogen gradients: Signaling molecules create spatial expression patterns Cell communication: Neighboring cells influence each other’s expression Anatomical structures: Different tissue regions have distinct expression profiles Quality control: Technical validation: Spatial patterns suggest data quality Noise detection: Random expression patterns may indicate technical issues Batch effects: Can manifest as spatial artifacts Examples in Spatial Biology Strong positive autocorrelation: Layer-specific genes in brain cortex Zonation markers in liver Tumor vs. stroma boundaries Developmental gradients Weak/no autocorrelation: Housekeeping genes (expressed everywhere) Technical noise Randomly distributed cell types 2.2.1 2.1 Location-Based Spatial Auto Correlation Key Statistic: Moran’s I Moran’s I measures Location-Dependent spatial autocorrelation by using k nearest neighbor CLICK HERE for more details When To use Exploring unknown spatial patterns Looking for gradual transitions or gradients Want comprehensive discovery of spatial genes Have complex tissue architecture without clear boundaries Formula Concept Compares observed spatial pattern vs. random spatial pattern: Calculates similarity between neighboring spots Standardizes against what you’d expect by chance Value Interpretation +1: Perfect positive autocorrelation (neighbors are identical) 0: No spatial pattern (random distribution) -1: Perfect negative autocorrelation (neighbors are opposite) Advantages: Unbiased discovery: No prior anatomical knowledge needed Continuous patterns: Detects gradients and smooth transitions Objective: Data-driven rather than annotation-dependent Limitations: Complex interpretation: Results may not map to known biology Statistical complexity: More sophisticated methods required Multiple testing: Many spatial relationships to test Practical Range &gt; +0.3: Strong spatial clustering/similarity 0 to +0.3: Moderate spatial pattern &lt; 0: Rare in biology (neighboring spots dissimilar) 2.2.1.1 2.1.1 Spatial Autocorrelation of known brain markers Here we perform the location based Spatial Autocorrelation on the 4 known brain markers with highest expression: # Known spatially Expressed genes to test for spatial autocorrelation genes_to_test &lt;- unlist(selected_genes) genes_to_test &lt;- unique(genes_to_test[!is.null(genes_to_test)]) # Calculate Moran&#39;s I for specific genes svg_results &lt;- FindSpatiallyVariableFeatures( seurat_obj , features = genes_to_test # Genes to test , selection.method = &quot;moransi&quot; # Selection method ) # Get Moran Statistics meta_features &lt;- svg_results@assays$SCT@meta.features # Create Table of Moran Statistics moran_summary &lt;- meta_features[genes_to_test, , drop = FALSE] %&gt;% mutate( Morans_I= round(MoransI_observed, 4) , P_Value = format(MoransI_p.value, scientific = TRUE, digits = 3) , Significant = as.numeric(P_Value) &lt; 0.05 , Spatial_Pattern = ifelse(Morans_I&gt; 0.1, &quot;Clustered&quot;, ifelse(Morans_I &lt; -0.1, &quot;Dispersed&quot;, &quot;Random&quot;)) ) %&gt;% select(Morans_I, P_Value, Significant, Spatial_Pattern) %&gt;% arrange(desc(Morans_I)) moran_summary %&gt;% knitr::kable(caption=&quot;Moran Statistics&quot;) Table 2.1: Moran Statistics Morans_I P_Value Significant Spatial_Pattern Mbp 0.5389 0e+00 TRUE Clustered Camk2a 0.5101 0e+00 TRUE Clustered Snap25 0.4695 0e+00 TRUE Clustered Gad1 0.4615 0e+00 TRUE Clustered Interpretation: We see strong spatial patterns in all 4 genes as expected (Moran’s I &gt; 0.3) 2.2.1.2 2.1.2 Spatial Autocorrelation of top 5 features identified by Moran’s I. seurat_obj &lt;- FindSpatiallyVariableFeatures(seurat_obj , assay = &quot;SCT&quot; , slot = &quot;scale.data&quot; , features = VariableFeatures(seurat_obj)[1:1000] , selection.method = &quot;moransi&quot;, x.cuts = 100, y.cuts = 100 ) top_spatial &lt;- head(SpatiallyVariableFeatures(seurat_obj, method = &quot;moransi&quot;),5) SpatialFeaturePlot(seurat_obj, features = top_spatial, # Gene name(s) or metadata column(s) to visualize ncol = 3, # Number of columns in plot layout (for multiple features) alpha = c(0.1, 1), # Transparency: c(min_expression, max_expression) max.cutoff = &quot;q95&quot;) # Maximum value cutoff for color scale 2.2.2 2.2 Differential Expression Between Anatomical Regions Compare gene expression between predefined tissue regions How it works: - Manual annotation: Researcher defines anatomical regions (e.g., cortex vs. white matter) - Region-based grouping: Spots assigned to discrete anatomical categories - Standard DE testing: Use traditional methods (Wilcoxon, DESeq2, etc.) between regions When to use Anatomical Region DE: You have clear anatomical knowledge Interested in specific region comparisons Want interpretable results for known structures Have well-defined boundaries in your tissue CLICK HERE for more details Advantages: Biologically interpretable: Based on known anatomy Statistical power: Uses established DE methods Clear comparisons: Discrete region contrasts Limitations: Requires prior knowledge: Need to know anatomy beforehand Discrete boundaries: Misses gradual transitions Manual bias: Subjective region definitions 2.2.2.1 Top DE Markers for Region B vs Region A # Example implementation # Manually annotate regions # We have 14 clusters, so we will name these Region A to O n_clusters &lt;- length(levels(seurat_obj$seurat_clusters)) region_names &lt;- paste0(&quot;Region_&quot;, LETTERS[1:n_clusters]) names(region_names) &lt;- levels(seurat_obj$seurat_clusters) seurat_obj &lt;- RenameIdents(seurat_obj, region_names) seurat_obj$cluster_names &lt;- Idents(seurat_obj) # Standard differential expression de_markers &lt;- FindMarkers( seurat_obj, , assay = &quot;SCT&quot; , test.use = &quot;wilcox&quot; # Wilcoxon rank sum test (default) , group.by = &quot;cluster_names&quot; , min.pct = 0.1 # minimum percentage of spots expressing gene , logfc.threshold = 0.25 # minimum log2 fold change , ident.1 = &quot;Region_B&quot; # first cluster to compare , ident.2 = &quot;Region_A&quot; # second cluster to compare ) de_markers$gene &lt;- rownames(de_markers) de_markers$gene &lt;- NULL Region_B_up &lt;- de_markers[de_markers$avg_log2FC &gt; 0, ] Region_B_up &lt;- Region_B_up[order(Region_B_up$p_val_adj, decreasing = F), ] Region_B_up %&gt;% head %&gt;% kable(caption=&quot;Top 5 genes upregulated in Region_B&quot;) Table 2.2: Top 5 genes upregulated in Region_B p_val avg_log2FC pct.1 pct.2 p_val_adj Camk2n1 0 1.0698325 1.000 1.000 0 Calb1 0 2.4065291 0.939 0.507 0 Camk2a 0 0.7095612 1.000 1.000 0 Nptxr 0 0.9278529 1.000 0.993 0 Lamp5 0 1.5576133 0.978 0.808 0 Atp1a1 0 0.7197658 1.000 1.000 0 note:pct.1 and pct.2 represent the percentage of spots each gene is expressed in within the case and control clusters respectively. #Subset for only Region A and B RegionA_B &lt;- subset(seurat_obj , subset = cluster_names %in% c(&quot;Region_A&quot;, &quot;Region_B&quot;) ) # Get expression data for these genes from SCT assay expr_for_heatmap &lt;- GetAssayData(RegionA_B , assay = &quot;SCT&quot; , layer = &quot;data&quot;)[rownames(Region_B_up)[1:5], ] # Create annotation for clusters annotation_col &lt;- data.frame( Cluster = seurat_obj@meta.data$seurat_clusters # cluster assignments , Spatial_X = seurat_obj@meta.data$spatial_x # x coordinates , Spatial_Y = seurat_obj@meta.data$spatial_y # y coordinates ) rownames(annotation_col) &lt;- colnames(seurat_obj) # Create heatmap pheatmap( expr_for_heatmap # expression matrix , cluster_rows = FALSE # don&#39;t cluster rows , cluster_cols = TRUE # cluster columns , annotation_col = annotation_col # column annotations , show_colnames = FALSE # hide column names , main = &quot;Expression of Top Differential Genes (SCT-normalized)&quot; # title , fontsize_row = 10 # row font size , color = viridis::viridis(100) # color palette ) cat(&quot;Total differentially expressed genes:&quot;, nrow(de_markers) , paste(&quot;
Genes upregulated in cluster 0:&quot;, sum(de_markers$avg_log2FC &gt; 0)) , paste(&quot;
Genes upregulated in cluster 1:&quot;, sum(de_markers$avg_log2FC &lt; 0)) , paste(&quot;
Significantly different genes (adj p &lt; 0.05):&quot;, sum(de_markers$p_val_adj &lt; 0.05)) , paste(&quot;
