Genes with logFC &gt; 1:&quot;, sum(abs(de_markers$avg_log2FC) &gt; 1)) ) ## Total differentially expressed genes: 4053 ## Genes upregulated in cluster 0: 1130 ## Genes upregulated in cluster 1: 2923 ## Significantly different genes (adj p &lt; 0.05): 846 ## Highly significant genes (p &lt; 0.001): 637 ## Genes with logFC &gt; 1: 308 Note: Here I have subsetted for only Region A and Region B demarkerplot &lt;- SpatialFeaturePlot(object = seurat_obj , features = rownames(de_markers)[1:3] , alpha = c(0.1, 1) , ncol = 3 ) clusterplot &lt;- SpatialDimPlot(seurat_obj, cells.highlight = CellsByIdentities(object = seurat_obj, idents = c(&quot;Region_A&quot;, &quot;Region_B&quot;)), facet.highlight = TRUE, ncol = 3) demarkerplot / clusterplot 2.2.2.2 Top DE Markers for ALL clusters For the public GitBook render, this demonstration uses the top variable features and caps the number of spots sampled per region. Remove features or increase max.cells.per.ident for a more exhaustive local analysis. marker_features &lt;- head(VariableFeatures(seurat_obj), 500) de_markers_all&lt;- FindAllMarkers( seurat_obj , features = marker_features , test.use = &quot;wilcox&quot; # Statistical test method (Wilcoxon rank-sum test) , only.pos = TRUE # Only return upregulated/positive markers , min.pct = 0.25 # Minimum percentage of cells expressing the gene , logfc.threshold = 0.25 # Minimum log fold-change threshold for testing , max.cells.per.ident = 250 # Keep public GitBook renders tractable ) # Top most significantly expressed gene for each region top_genes_pval &lt;- de_markers_all %&gt;% arrange(p_val_adj) %&gt;% distinct(cluster, .keep_all = T) %&gt;% select(gene, avg_log2FC, p_val_adj, cluster ) top_genes_pval %&gt;% knitr::kable(caption=&quot;Top most significantly expressed gene for each region&quot;) Table 2.3: Top most significantly expressed gene for each region gene avg_log2FC p_val_adj cluster Camk2n1 Camk2n1 1.402586 0 Region_B Doc2g Doc2g 4.280877 0 Region_G Mbp1 Mbp 2.631323 0