_adj) %&gt;% distinct(cluster, .keep_all = T) %&gt;% select(gene, avg_log2FC, p_val_adj, cluster ) top_genes_pval %&gt;% knitr::kable(caption=&quot;Top most significantly expressed gene for each region&quot;) Table 2.4: Top most significantly expressed gene for each region gene avg_log2FC p_val_adj cluster Camk2n1 Camk2n1 1.4025857 0 Region_B Doc2g Doc2g 4.2808767 0 Region_G Mbp1 Mbp 2.6313231 0 Region_F Penk1 Penk 2.7446572 0 Region_E 3110035E14Rik 3110035E14Rik 2.4198182 0 Region_A Gpr88 Gpr88 2.6543818 0 Region_C Shisa81 Shisa8 3.7579074 0 Region_K Hap11 Hap1 2.5354517 0 Region_H mt-Co1 mt-Co1 0.6538976 0 Region_D Olfm12 Olfm1 1.3408034 0 Region_I Fabp72 Fabp7 3.9501373 0 Region_L Fth12 Fth1 0.7383636 0 Region_J Ttr2 Ttr 6.3966124 0 Region_M # Plot top significant genes (by p-value) demarkerplot &lt;- SpatialFeaturePlot(seurat_obj, , features = top_genes_pval$gene[1:3] , ncol = 3 # Adjust columns based on number of clusters , alpha = c(0.1, 1) # Transparency settings , max.cutoff = &quot;q95&quot; ) clusterplot &lt;- SpatialDimPlot(seurat_obj, cells.highlight = CellsByIdentities(object = seurat_obj, idents = c(&quot;Region_G&quot;, &quot;Region_A&quot;, &quot;Region_B&quot;)), facet.highlight = TRUE, ncol = 3) demarkerplot / clusterplot loc &lt;- &quot;cache/stxBrain_anterior2_processed_1.RDS&quot; if(!file.exists(loc) ) {saveRDS(seurat_obj, loc)}
